const items = $input.all();
const results = [];

for (const item of items) {
  const from = item.json.from || '';
  const subject = (item.json.subject || '').toLowerCase();
  const body = (item.json.snippet || item.json.textPlain || '').toLowerCase();

  // Parse name from email
  const nameMatch = from.match(/^([^<]+)/);
  const name = nameMatch ? nameMatch[1].trim() : from.split('@')[0];

  // Parse company from domain
  const domainMatch = from.match(/@([^>]+)/);
  const domain = domainMatch ? domainMatch[1].trim() : '';
  const company = domain.split('.')[0].charAt(0).toUpperCase() + domain.split('.')[0].slice(1);

  // Detect interest from keywords
  const interests = [];
  const keywordMap = {
    'pricing': 'Pricing Inquiry',
    'demo': 'Demo Request',
    'trial': 'Trial Interest',
    'integration': 'Integration Question',
    'partnership': 'Partnership',
    'quote': 'Quote Request',
    'proposal': 'Proposal Request'
  };

  for (const [keyword, interest] of Object.entries(keywordMap)) {
    if (subject.includes(keyword) || body.includes(keyword)) {
      interests.push(interest);
    }
  }

  const leadScore = interests.length >= 2 ? 'hot' : interests.length === 1 ? 'warm' : 'cold';

  results.push({
    json: {
      name: name,
      email: from,
      company: company,
      domain: domain,
      interest: interests.join(', ') || 'General Inquiry',
      leadScore: leadScore,
      emailSubject: item.json.subject,
      capturedAt: new Date().toISOString(),
      status: 'new'
    }
  });
}
return results;

